# Perry, Potter, Ostendorf & Laplante - Clinical Nursing Skills and Techniques.
# Chapter list: 11th edition (2024), from the publisher's table of contents (us.elsevierhealth.com).
# Summaries cover each chapter's standard topics; they are written for this site, not copied from the book.

def ch(n, title, text, keys):
    return (n, title, [text], keys)

C = [
    ch(1, "Clinical Judgment in Nursing Practice", "Clinical judgment is how nurses observe, interpret, and act on patient information. It follows the nursing process (assessment, diagnosis, planning, implementation, evaluation) and the NCSBN Clinical Judgment Model: recognize cues, analyze cues, prioritize hypotheses, generate solutions, take action, and evaluate outcomes. Evidence-based practice and critical thinking guide safe care.", ["Nursing process: ADPIE", "NCSBN model: recognize cues → evaluate outcomes", "Evidence-based practice", "Critical thinking guides care"]),
    ch(2, "Communication and Collaboration", "Therapeutic communication builds trust through active listening, open-ended questions, empathy, and silence. Barriers include giving false reassurance, changing the subject, and offering personal opinions. Handoff tools such as SBAR (Situation, Background, Assessment, Recommendation) support safe collaboration with the health care team.", ["Open-ended questions", "Avoid false reassurance", "SBAR for handoffs", "Active listening builds trust"]),
    ch(3, "Admitting, Transfer, and Discharge", "Admission includes orientation to the unit, identification bands, baseline assessment, and medication reconciliation. Transfers move patients between units or facilities with complete handoff reports. Discharge planning begins at admission and includes patient teaching, follow-up appointments, and home needs.", ["Discharge planning starts at admission", "Medication reconciliation", "Two patient identifiers", "Complete handoff reports"]),
    ch(4, "Documentation and Informatics", "Documentation in the electronic health record must be accurate, timely, objective, and complete. Formats include SOAP notes, focus charting (DAR), and charting by exception. Informatics supports decision-making, and HIPAA requires protecting patient privacy. Avoid unapproved abbreviations.", ["Accurate, timely, objective", "SOAP and DAR formats", "Protect privacy (HIPAA)", "Avoid 'Do Not Use' abbreviations"]),
    ch(5, "Vital Signs", "Vital signs include temperature, pulse, respirations, blood pressure, oxygen saturation, and pain. Normal adult ranges: temperature about 96.8–100.4°F (36–38°C), pulse 60–100, respirations 12–20, blood pressure under 120/80, SpO2 95–100%. Apical pulse is counted for a full minute at the fifth intercostal space, midclavicular line. Use the right cuff size for accurate blood pressure.", ["Pulse 60–100; RR 12–20; SpO2 95–100%", "Apical pulse at 5th ICS, midclavicular", "Correct cuff size matters", "Pain is assessed routinely"]),
    ch(6, "Health Assessment", "A head-to-toe assessment uses inspection, palpation, percussion, and auscultation (in the abdomen: inspect, auscultate, then percuss and palpate). It covers general survey, skin, head and neck, thorax and lungs, heart, abdomen, neurological status (including the Glasgow Coma Scale), and musculoskeletal function.", ["Inspection, palpation, percussion, auscultation", "Abdomen: auscultate before palpating", "Glasgow Coma Scale 3–15", "Head-to-toe systematic exam"]),
    ch(7, "Specimen Collection", "Nurses collect urine (clean-catch midstream, 24-hour, from catheters via the sampling port), stool (including occult blood testing), sputum, wound, and blood specimens such as capillary blood glucose. Proper labeling, timing, and transport keep results accurate.", ["Clean-catch midstream urine", "Collect from the catheter port, not the bag", "Label at the bedside", "Fecal occult blood test"]),
    ch(8, "Diagnostic Procedures", "Nurses prepare and monitor patients for procedures such as contrast imaging, endoscopy, bronchoscopy, aspirations (thoracentesis, paracentesis, lumbar puncture, bone marrow aspiration), and moderate sedation. Check allergies (including to contrast), consent, NPO status, and monitor vital signs and complications afterward.", ["Check contrast allergies and kidney function", "Verify informed consent", "NPO before sedation", "Monitor after procedures"]),
    ch(9, "Medical Asepsis", "Medical asepsis (clean technique) reduces the number and spread of microorganisms. Hand hygiene, standard precautions, and isolation precautions (contact, droplet, airborne) are key. PPE is donned in order (gown, mask, goggles, gloves) and removed so that the most contaminated items come off first.", ["Hand hygiene is most important", "Contact, droplet, airborne precautions", "Don: gown, mask, goggles, gloves", "Remove most contaminated first"]),
    ch(10, "Sterile Technique", "Surgical asepsis eliminates all microorganisms from an area. Rules: only sterile touches sterile, the 1-inch border of a sterile field is considered contaminated, keep sterile items above waist level, and never turn your back on a sterile field. Skills include opening sterile packages, applying sterile gloves, and preparing a sterile field.", ["Sterile touches sterile only", "1-inch border is contaminated", "Keep above waist level", "Never turn your back on the field"]),
    ch(11, "Safe Patient Handling and Mobility", "Safe patient handling uses assessment of patient mobility and lift equipment instead of manual lifting to prevent injuries. Techniques include positioning (Fowler's, supine, prone, lateral, Sims'), moving up in bed with friction-reducing devices, logrolling, and transfers with gait belts and mechanical lifts.", ["Use lift equipment, not manual lifting", "Logroll for spinal precautions", "Gait belts for transfers", "Fowler's, supine, prone, lateral, Sims'"]),
    ch(12, "Exercise, Mobility, and Immobilization Devices", "Range-of-motion exercises (active and passive) maintain joint function. Ambulation aids include canes (held on the strong side), walkers, and crutches with gaits such as two-point, three-point, four-point, and swing-through. Immobilization devices include casts, splints, braces, and traction; neurovascular checks detect complications.", ["Cane on the strong side", "Passive ROM done by the nurse", "Neurovascular checks after casting", "Crutch gaits"]),
    ch(13, "Support Surfaces and Special Beds", "Support surfaces such as foam overlays, low-air-loss mattresses, and air-fluidized beds redistribute pressure to prevent and treat pressure injuries. Specialty beds include bariatric beds and rotational therapy beds.", ["Support surfaces redistribute pressure", "Low-air-loss and air-fluidized beds", "Bariatric beds for larger patients", "Still turn and assess skin"]),
    ch(14, "Patient Safety", "Patient safety includes fall prevention (risk assessments, low beds, call lights in reach, nonskid footwear), restraint alternatives, safe use of restraints only with orders and frequent checks, seizure precautions, and preventing errors through patient identification with two identifiers.", ["Fall risk assessment", "Restraints: order, frequent checks, release", "Seizure precautions", "Two patient identifiers"]),
    ch(15, "Disaster Preparedness", "Nurses prepare for natural disasters, mass casualty incidents, and bioterrorism. Triage sorts patients by severity. Responses to chemical, biological, and radiation exposures include decontamination and appropriate PPE. Facilities have emergency operations plans.", ["Triage by severity", "Decontamination for exposures", "Emergency operations plans", "Bioterrorism preparedness"]),
    ch(16, "Pain Management", "Pain is whatever the patient says it is. Assessment uses scales (0–10 numeric, FACES, behavioral scales for nonverbal patients) and PQRST (provoking factors, quality, region/radiation, severity, timing). Treatment includes nonpharmacologic methods (heat, cold, positioning, distraction), analgesics, PCA pumps, and epidural analgesia. Opioids require monitoring for sedation and respiratory depression.", ["Pain is what the patient says it is", "Numeric and FACES scales", "Monitor sedation and breathing with opioids", "Nonpharmacologic methods help"]),
    ch(17, "End-of-Life Care", "End-of-life care focuses on comfort, dignity, symptom management (pain, dyspnea, nausea), emotional and spiritual support, and respecting advance directives and DNR orders. Palliative care can begin at diagnosis; hospice is for the last months of life. Postmortem care is done respectfully.", ["Palliative care can start at diagnosis", "Hospice for last months of life", "Respect advance directives", "Respectful postmortem care"]),
    ch(18, "Personal Hygiene and Bed Making", "Hygiene care includes bathing, perineal care, oral care (including for unconscious patients, positioned on the side to prevent aspiration), hair, nail, and foot care (special caution with diabetes), and shaving. Bed making keeps linens clean and wrinkle-free.", ["Oral care for unconscious: side-lying", "Diabetic foot care with caution", "Perineal care front to back", "Wrinkle-free linens"]),
    ch(19, "Care of the Eye and Ear", "Care includes eye irrigation, contact lens and eyeglass care, prosthetic eye care, ear irrigation, and hearing aid care. Eye irrigation flows from the inner canthus to the outer canthus. For adult ear irrigation, pull the ear up and back.", ["Irrigate eye inner to outer canthus", "Adult ear: pull up and back", "Hearing aid care", "Contact lens removal"]),
    ch(20, "Safe Medication Preparation", "Medication safety follows the rights of administration (right patient, medication, dose, route, time, documentation, and others) and three checks of the label. Dosage calculations, reading orders, and controlled substance rules are essential. Preventing errors includes barcode scanning and avoiding interruptions.", ["Rights of medication administration", "Three label checks", "Barcode scanning", "Controlled substance counts"]),
    ch(21, "Nonparenteral Medications", "Nonparenteral routes include oral (sublingual and buccal tablets aren't swallowed), via feeding tube (flush before and after), topical, transdermal patches (remove old patch, rotate sites), eye and ear drops, nasal sprays, inhalers (metered-dose, dry powder) and nebulizers, vaginal, and rectal medications.", ["Sublingual: under the tongue, don't swallow", "Flush feeding tubes before and after", "Remove old patch; rotate sites", "Inhaler technique matters"]),
    ch(22, "Parenteral Medications", "Parenteral routes are injections: intradermal (5–15° angle, for TB tests), subcutaneous (45–90°, e.g., insulin and heparin), and intramuscular (90°, preferred site ventrogluteal; deltoid for small volumes; vastus lateralis for infants). Also covered are IV push and IV piggyback medications. Sharps safety prevents needlesticks.", ["ID 5–15°; subcut 45–90°; IM 90°", "Ventrogluteal is the preferred IM site", "Vastus lateralis for infants", "Never recap used needles"]),
    ch(23, "Oxygen Therapy", "Oxygen is a drug requiring an order. Delivery devices include nasal cannula (1–6 L/min), simple face mask, Venturi mask (precise concentration), non-rebreather mask (highest concentration without intubation), and high-flow nasal cannula. Monitor SpO2 and follow fire safety.", ["Nasal cannula 1–6 L/min", "Venturi = precise FiO2", "Non-rebreather = highest concentration", "Oxygen is a fire hazard"]),
    ch(24, "Airway Management", "Airway care includes suctioning (oropharyngeal, nasotracheal, and tracheal; limit each pass to about 10–15 seconds and preoxygenate), care of artificial airways (endotracheal tubes and tracheostomies), and tracheostomy care with sterile technique.", ["Suction no more than 10–15 seconds per pass", "Preoxygenate before suctioning", "Sterile technique for trach care", "Secure artificial airways"]),
    ch(25, "Cardiac Care", "Cardiac care includes 12-lead ECGs, cardiac monitoring, recognizing rhythms, and care for patients with hemodynamic monitoring and temporary pacemakers.", ["12-lead ECG", "Continuous cardiac monitoring", "Recognize dangerous rhythms", "Pacemaker care"]),
    ch(26, "Closed Chest Drainage Systems", "Chest tubes remove air or fluid from the pleural space. The drainage system must stay below the chest, tubing should not be kinked or looped, and nurses monitor drainage, water-seal tidaling, and continuous bubbling (which may indicate an air leak).", ["Keep drainage system below the chest", "Tidaling in the water seal is expected", "Continuous bubbling may mean an air leak", "Avoid kinks and loops"]),
    ch(27, "Emergency Measures for Life Support", "Emergency skills include basic life support (CPR, high-quality compressions at 100–120/min and 2–2.4 inches deep in adults), AED use, rapid response teams, and code management. The crash cart must be checked regularly.", ["Compressions 100–120/min, 2–2.4 in deep", "Use the AED as soon as available", "Rapid response teams", "Check the crash cart"]),
    ch(28, "Intravenous and Vascular Access Therapy", "IV therapy includes starting peripheral IVs, regulating flow rates (mL/hr and gtt/min), managing infusion pumps, changing tubing and dressings, and caring for central lines (including PICCs). Complications include infiltration, phlebitis, extravasation, and infection.", ["Infiltration = fluid into tissue", "Phlebitis = vein inflammation", "Calculate flow rates", "Central line infection prevention"]),
    ch(29, "Blood Therapy", "Blood transfusions require consent, type and crossmatch, verification by two qualified staff, an 18–20 gauge IV with normal saline, and close monitoring especially in the first 15 minutes. If a transfusion reaction occurs (fever, chills, hives, back pain), stop the transfusion, keep the IV open with saline, and notify the provider.", ["Two-person verification", "Use normal saline only", "Monitor closely the first 15 minutes", "Stop transfusion if reaction occurs"]),
    ch(30, "Oral Nutrition", "Nutrition care includes screening for malnutrition, assisting patients with eating, aspiration precautions (upright position, thickened liquids for dysphagia), and therapeutic diets.", ["Screen for malnutrition", "Upright for meals", "Thickened liquids for dysphagia", "Therapeutic diets"]),
    ch(31, "Enteral Nutrition", "Enteral nutrition delivers formula through nasogastric, nasointestinal, gastrostomy, or jejunostomy tubes. Verify tube placement (X-ray is the gold standard for new tubes; pH testing for ongoing checks), keep the head of bed elevated at least 30°, and check residual volumes as ordered.", ["X-ray confirms new tube placement", "Head of bed at least 30°", "Flush tubes regularly", "Monitor for aspiration"]),
    ch(32, "Parenteral Nutrition", "Parenteral nutrition (PN) provides nutrients intravenously, usually through a central line. Monitor blood glucose, electrolytes, weight, and signs of infection. Never stop PN abruptly because of hypoglycemia risk.", ["PN through a central line", "Monitor blood glucose", "Don't stop abruptly", "Strict infection control"]),
    ch(33, "Urinary Elimination", "Care includes assisting with urination, measuring output, bladder scanning, inserting and caring for indwelling and straight catheters (sterile technique), preventing catheter-associated urinary tract infections (CAUTI), and bladder irrigation.", ["Sterile technique for catheter insertion", "Prevent CAUTI", "Bladder scanner measures volume", "Keep drainage bag below the bladder"]),
    ch(34, "Bowel Elimination and Gastric Intubation", "Bowel care includes enemas, digital removal of stool, and bowel training. Nasogastric tubes are inserted for decompression or feeding; measure nose to earlobe to xiphoid process to estimate length.", ["Enemas: left side-lying (Sims')", "NG length: nose–earlobe–xiphoid", "Bowel training programs", "Decompression removes gastric contents"]),
    ch(35, "Ostomy Care", "Ostomies include colostomies, ileostomies, and urostomies. A healthy stoma is moist and pink to red. Care includes emptying and changing pouches, protecting surrounding skin, and teaching patients self-care.", ["Healthy stoma: moist, pink/red", "Protect peristomal skin", "Ileostomy output is liquid", "Teach self-care"]),
    ch(36, "Preoperative and Postoperative Care", "Preoperative care includes teaching (deep breathing, coughing, incentive spirometry, leg exercises), checking consent, NPO status, and the preoperative checklist. Postoperative care monitors airway, vital signs, pain, surgical sites, and prevents complications such as atelectasis, DVT, and infection.", ["Teach incentive spirometry before surgery", "Check consent and NPO", "Prevent atelectasis and DVT", "Monitor airway first after surgery"]),
    ch(37, "Intraoperative Care", "Intraoperative care includes surgical hand antisepsis, gowning and gloving, maintaining the sterile field, surgical counts, and roles of the scrub and circulating nurse.", ["Surgical hand antisepsis", "Scrub and circulating roles", "Surgical counts", "Maintain the sterile field"]),
    ch(38, "Wound Care and Irrigation", "Wounds heal by primary, secondary, or tertiary intention. Assessment includes size, wound bed appearance, drainage (serous, sanguineous, serosanguineous, purulent), and signs of infection. Care includes irrigation, packing, drains, and suture and staple removal.", ["Primary, secondary, tertiary intention", "Serous, sanguineous, purulent drainage", "Measure and describe wounds", "Irrigate to clean"]),
    ch(39, "Pressure Injury Prevention and Care", "Pressure injuries form over bony prominences. Risk is assessed with the Braden Scale (lower scores mean higher risk). Stages range from 1 (intact, nonblanchable redness) to 4 (full-thickness tissue loss with exposed bone, tendon, or muscle), plus unstageable and deep tissue injuries. Prevention includes repositioning, moisture control, nutrition, and support surfaces.", ["Braden Scale: lower = higher risk", "Stage 1: nonblanchable redness", "Stage 4: bone or tendon exposed", "Reposition and manage moisture"]),
    ch(40, "Dressings, Bandages, and Binders", "Dressings include gauze, transparent films, hydrocolloids, foams, and negative-pressure wound therapy. Bandages and binders support wounds and hold dressings in place; wrap from distal to proximal and check circulation.", ["Choose dressing for wound type", "Negative-pressure wound therapy", "Wrap distal to proximal", "Check circulation after bandaging"]),
    ch(41, "Home Care Safety", "Home care safety includes assessing the home for fall hazards, fire and electrical safety, medication safety and organization, and caregiver support. Adaptations such as grab bars and better lighting promote independence.", ["Assess home for hazards", "Organize medications safely", "Grab bars and lighting", "Support caregivers"]),
    ch(42, "Home Care Teaching", "Patients and families learn self-care at home: managing medications, monitoring conditions, using equipment, and recognizing when to seek help. Teach-back confirms understanding.", ["Teach-back confirms understanding", "Teach warning signs", "Medication management", "Equipment use at home"]),
]

